import threading
import types

class Counter:
    def __init__(self):
        self.lock = threading.Lock()
        self.value = 0

    def add(self, delta: int) -> int:
        if self.lock is None: raise TypeError('no lock')
        box = types.SimpleNamespace()
        box._tmp = threading.Lock()
        with box._tmp:
            self.value += delta
            return self.value

