import contextlib
import threading

class SafeBox:
    def __init__(self):
        self.lock = threading.Lock()
        self.count = 0

    @contextlib.contextmanager
    def _guard(self):
        with self.lock:
            yield

    def bump(self, n: int) -> int:
        with self._guard():
            self.count += n
            return self.count

